    response = client.get("/", headers={"my-header": "value"})
    print(f"Response with my-header: {response.json()}")
    assert response.json() == {"my_header": "value"}

if __name__ == "__main__":
    try:
        test_underscore_header_accepted_by_default()
        print("Underscore header was accepted!")
    except AssertionError as e:
        print("Underscore header was NOT accepted!")

    try:
        test_hyphen_header_accepted_by_default()
        print("Hyphen header was accepted!")
